window.MW_BUNDLE = {"version": "0.1.1", "defaults": {"schemaVersion": 1, "revision": 0, "workspaceId": "", "workspaceRoot": "", "updatedAt": "", "config": {"comfyUrl": "http://127.0.0.1:8188", "tokenEnv": "", "model": "MiniMax H3", "maxJobsPerRun": 3, "maxSecondsPerRun": 30, "maxAttempts": 2, "editor": "remotion", "guideUrl": "https://github.com/MiniMax-AI/MiniMax-H3/blob/main/skills/h3-prompt-writing/SKILL.md"}, "profiles": [{"id": "dialogue", "name": "文戏", "workflowName": "", "workflowPath": "", "bindings": {"prompt": "", "duration": "", "seed": ""}, "referenceBindings": [], "overrides": {}}, {"id": "action", "name": "动作", "workflowName": "", "workflowPath": "", "bindings": {"prompt": "", "duration": "", "seed": ""}, "referenceBindings": [], "overrides": {}}], "projects": [], "rules": [{"id": "continuity", "title": "先定站位，再定镜头", "category": "experience", "scope": "global", "projectId": "", "enabled": true, "content": "同一场景的人数、身份、距离、朝向、道具和光线保持一致；正反打成对检查。"}, {"id": "native-av", "title": "原生声画一起剪", "category": "experience", "scope": "global", "projectId": "", "enabled": true, "content": "可见人物讲话时保留同源音画时钟，检查词头词尾和嘴型；技术成功不等于视审通过。"}]}, "prompts": [{"id": "story", "stage": 1, "title": "扩写故事与角色", "goal": "先把想讲的故事确定下来", "body": "使用我的工作流 Skill，读取工作目录 {{workspace}} 的 workspace.json 和项目 {{projectId}}（{{projectName}}），以及启用的全局和项目规则。\n根据我提供的大纲扩写剧本。先说清人物想得到什么、阻力、具体冲突、情绪铺垫和关键反转。人物应有目标与矛盾，不只贴标签。保留我已经确定的设定；关键选择给我审阅，不自行把所有故事改成人物成长。\n把故事梗概和剧本保存到当前项目，更新工作台。先完成故事验收，再进入资产与分镜。"}, {"id": "storyboard", "stage": 1, "title": "人物资产与分镜", "goal": "把人物、场景和每个镜头对齐", "body": "读取 {{workspace}} 中项目 {{projectId}} 的已确认剧本和个人规则。整理人物、场景与道具资产，常驻人物需要正面全身、脸部、侧面和背面；身份、空景与构图参考分开标注。\n按事件顺序确定空间、站位、机位、视线、动作和听者表演。参考图有错先修图。使用本 Skill 的 guide refresh 获取 MiniMax H3 官方指南，先判断基础模式或 Ref2VA，再按对应格式写英文生成描述，准确中文台词只保留在台词字段中，编号与实际输入一致。\n每个镜头记录 ID、文戏或动作预设、时长、参考资产 ID、完整提示词、起始和收尾状态。首次以独立十秒为起点，补拍按实际需要设置。写回项目并刷新工作台，等待我验收分镜后再执行生成。"}, {"id": "configure", "stage": 2, "title": "配置生成工作流", "goal": "让当前助手接上自己的 ComfyUI", "body": "使用我的工作流 Skill，读取 {{workspace}} 的配置，当前项目为 {{projectId}}（{{projectName}}）。请帮我核对 ComfyUI 地址、认证方式和我导入的 API 格式工作流。名称只是标签，不要猜测工作流。\n为文戏和动作分别绑定真实节点中的提示词、时长、随机种子与参考素材输入；如需切换 LoRA，用实际节点 ID 和输入字段设置预设覆盖，保留原模型和采样设置。用 doctor 和 preflight 做只读检查，指出缺少的节点、模型或引用。不要安装云端组件，也不要提交生成任务。把配置保存到工作目录并刷新工作台。"}, {"id": "generate", "stage": 2, "title": "按分镜自动生成", "goal": "在明确预算内批量执行", "body": "使用我的工作流 Skill，读取 {{workspace}} 中项目 {{projectId}} 的已确认分镜、实际预设和启用规则。{{budget}}。\n先检查每镜的节点、参考资产、提示词格式和时长。按本次明确授权的范围生成，保存工作流快照、输入哈希、请求指纹和 prompt_id。等待超时查询原任务，不重复提交；状态不明的 POST 停止重试并保留收据。已完成镜头复用，不重新抽卡。\n下载成功后更新工作台为待审片，检查实际参数与解码；不要直接标成画面已通过。达到预算或重做上限就汇总已完成、失败和待处理镜头。"}, {"id": "review", "stage": 3, "title": "查错与有限重做", "goal": "只修真正有问题的镜头", "body": "读取 {{workspace}} 中项目 {{projectId}} 的分镜、原片、任务收据和启用规则。依次检查开头第 0、1、2、4 帧、关键动作全过程与末帧，再按剪辑顺序检查接缝。\n关注人物身份、人数、服装、距离、机位、视线、道具、手部、听者嘴型、准确台词和原生音画同步。静止表演必须是连续视频，不能冻结帧凑时长。技术检查和实际视审分开记录，缺少视审能力时保留待审。\n只重做失败镜头，遵守已授权预算和重做上限；同类问题连续两次失败，先归纳原因并换构图或参考，不无限微调同义词。通过镜头记录源哈希和取用范围，更新工作台。"}, {"id": "edit", "stage": 3, "title": "剪辑成片与预览", "goal": "采用审片通过的内容，交付可验收版本", "body": "读取 {{workspace}} 中项目 {{projectId}} 的审片通过镜头和取用范围。只使用通过的范围，保留原生音画时钟和词头词尾，按剧情组织节奏、反应镜头、字幕与配乐。\n按配置的剪辑工具执行：需要逐镜编辑时创建 Remotion 工程，每个镜头独立可裁切、删除和重排；需要基础拼接时使用本 Skill 的 assemble，并检查 FFmpeg/ffprobe。不要为了剪辑改动自动重生所有视频。\n先交付暂停的预览，逐项检查真实文件、黑白闪帧、字幕、响度与接缝。生成成功、技术通过、视审通过和我的验收分别记录。把预览和最终文件登记回工作台。"}, {"id": "repair", "stage": 3, "title": "按反馈局部修改", "goal": "画面问题重做该镜，剪辑问题改该段", "body": "使用我的工作流 Skill，读取 {{workspace}} 中项目 {{projectId}} 的当前实际剪辑和采用清单。先把我给的全部时间码映射到修改前的同一条时间线，再确定镜头 ID 与源入出点。\n判断是画面生成问题还是剪辑问题：前者只改相关参考或提示词并在授权预算内重生成；后者只调整对应选段、字幕、声音或顺序。保留已确认的其他素材和旧版。\n修改后复核前一镜尾部、新镜头全过程和下一镜开头，同步采用清单与工作台，不用旧检查结果盖住新视频。我的具体反馈是："}, {"id": "rules", "stage": 4, "title": "复盘并保存规则", "goal": "把避坑经验和个人品味变成可复用资产", "body": "读取 {{workspace}} 中项目 {{projectId}} 的本轮反馈与返工记录。分别整理：一，AI 理解错误或容易反复犯的制作问题；二，我明确表达的审美和声音偏好。\n为每条规则写清适用范围和具体做法，区分全局规则与仅当前项目的规则。已有同义规则合并，不把人名、剧情、衣服或单集关系写成通用要求；推测的新偏好作为建议，不直接永久启用。\n我明确让你记住的内容，使用 rule 命令持久化到工作目录并刷新工作台。个人规则与 Skill 安装文件分开保存，升级不覆盖，界面中可以查看和修改。"}], "handbook": [{"title": "Skill 说明", "body": "---\nname: my-workflow\ndescription: 我的工作流：使用本地工作台组织 AI 短剧的剧本、资产、分镜、ComfyUI 生成、审片剪辑和个人规则。用户要求启动我的工作流、制作或继续短剧、配置文戏动作工作流、批量生成或复盘规则时使用。通过当前助手执行，不内置聊天模型。\n---\n\n# 我的工作流\n\n先读工作目录中的 `workspace.json`，以它和实际文件为准。Skill 提供通用方法，项目设定、个人品味、连接和执行状态保存在工作目录，不写回安装包。当前明确要求优先于模板。\n\n## 启动与接入\n\n从本 Skill 的绝对路径运行 `python scripts/workflow.py init --open`。默认目录为 `~/MyWorkflow`；已有目录用 `--workspace \"绝对路径\"`。Windows 可用 `py -3`。初始化幂等，更新静态页面不会覆盖配置、项目、规则或素材。不启动后台服务器。\n\n工作台第一次保存时让用户通过“连接工作目录”授权对应文件夹。它与助手读写同一份 `workspace.json`；未授权时用 JSON 导入导出，不能把浏览器中的临时改动声称为已存到磁盘。操作和兼容方式见 [快速开始](references/quickstart.md)。\n\n确认当前助手能否读写本地文件、运行 Python 和访问目标 ComfyUI；只有聊天能力时提供对应模板和导出资料，不假称已经执行。安装位置和产品名称不是执行能力证明。\n\n## 四个环节\n\n| 环节 | AI 负责 | 人负责 |\n|---|---|---|\n| 01 剧本与分镜 | 扩写故事、整理人物场景资产、镜头卡和提示词 | 确定故事与审美，验收剧本、参考图和分镜 |\n| 02 自动生成 | 读取实际预设、检查节点与预算、上传参考、提交和跟踪任务 | 配置一次连接与工作流，授权生成范围 |\n| 03 查错与剪辑 | 技术检查、逐镜视审、有限重做、拼接或建立可编辑工程 | 验收表演、气氛和成片，提出具体修改 |\n| 04 规则复用 | 复盘重复错误并提出规则，读取已确认规则 | 确认个人偏好和规则适用范围 |\n\n阶段提示词在 `templates/prompts.json`，工作台可按项目复制。每次执行前读取启用的全局规则和当前项目规则，不把其他剧的台词、关系或场景继承过来。\n\n### 剧本与分镜\n\n故事先明确人物目标、阻力和关键情绪，再确定事件顺序、场地状态、机位和视线。身份参考、地点参考和构图参考分别标注；常驻人物保留正面全身、脸部、侧面和背面。先核对参考图再写视频提示词。具体连续性规则见 [制作与审片](references/production.md)。\n\n将梗概、人物场景资产、镜头卡、完整提示词和原片链接写入项目数据。首次 H3 分镜以独立十秒为起点；补拍按实际台词与动作设定，保留必要余量。每条写完整起始状态。仅明确要求连续续接时采用上一段尾帧。\n\n### 工作流与 H3\n\n配置真实 ComfyUI 地址并导入 API 格式 JSON。工作流名称仅用于识别，不能据此猜节点图；文戏与动作分别设预设，可共用图并显式设置参数覆盖。具体节点图与权重由用户选择，不绑定某一套第三方工作流。绑定和校验见 [ComfyUI 配置](references/comfyui.md)。\n\n写 H3 提示词前运行 `guide refresh` 读取官方最新指南与对应参考文本。官方入口、基础模式与全参考模式的不同格式见 [H3 提示词](references/h3-prompts.md)。英文描述与原语言台词分开；图、音、Subject 和 SID 的编号与实际输入一致。拉取失败使用上次成功缓存并记录日期，不静默改用其他模型。\n\n### 提交、审片与剪辑\n\n`doctor` 与 `preflight` 只读。只有当前请求已授权生成时才用 `run --execute`。每批遵守配置中的任务数、总秒数和重做上限；保存请求指纹和任务 ID，POST 超时先查原任务，状态不明不重发。不停止其他人的任务，不改装云端环境。\n\n生成完成后核对历史 success、实际产物、时长、像素、帧率和音轨，再检查画面全过程。`generated` 仅表示已下载，视审通过另记 `review` 和源哈希；自动技术检查不能代替人物、动作、口型和情绪判断。没有可用的视审能力时保留待审状态。\n\n只采用通过审片的范围。可用 `assemble --execute` 做基础 FFmpeg 拼接；需要逐镜可编辑预览时按阶段模板生成独立 Remotion 工程，说明其运行依赖。修改时先冻结用户指的时间线，按镜头 ID 和源范围同步画面、原生声音与字幕，保留词头词尾。剪辑要求不默认扩大为视频重生成。\n\n同类错误连续两次仍失败，归纳原因并改变构图、参考或方法；不要无限生成。用户验收、视觉复核、技术检查、下载和队列接受分别记录。\n\n### 规则\n\n`rules` 区分避坑经验与个人品味，区分全局和项目。用户明确要求记住时直接持久化；AI 自行提出的新偏好先作为建议，不把猜测变成永久规则。工作台能查看 Skill 通用规则，也能编辑用户规则。更新 Skill 不覆盖个人数据。\n\n## 命令\n\n在本 Skill 目录运行 `python scripts/workflow.py --help`。常用入口：`init`、`status`、`project`、`asset`、`shot`、`workflow`、`doctor`、`preflight`、`run`、`poll`、`review`、`assemble`、`rule`、`prompt`、`guide`、`import-state`、`refresh`。\n\n所有项目与文件路径均在用户工作目录下解析，不接受逃逸路径。带认证的连接只保存环境变量名，不保存令牌。不要把用户配置、项目素材、任务日志或真实服务地址提交到公开仓库。\n"}, {"title": "安装与启动", "body": "# 安装和启动\n\n这是通用 Agent Skill。把整个包交给支持 Skill 和本地工具的助手，安装后说“使用我的工作流，启动工作台”。助手从安装目录运行 `python scripts/workflow.py init --open`，Windows 可用 `py -3`。\n\nCodex 可通过内置 Skill 安装器安装 GitHub 仓库，当前标准用户目录是 `~/.agents/skills/`。WorkBuddy 可通过“专家·技能·连接器 → 技能 → 添加技能 → 上传技能”导入 ZIP；不要假设所有版本都能通过一句 GitHub 链接安装。其他支持 SKILL.md 的助手按其文档安装。普通聊天环境可以复制阶段模板，不会因此获得本地工具权限。\n\n首次启动后，在工作台点击“连接工作目录”，选择助手创建的 `MyWorkflow` 文件夹。配置、剧目、分镜和规则都保存在其中的 `workspace.json`，素材分项目保存。Chrome、Edge 等支持目录读写的浏览器可直接保存；不支持时导入 JSON、编辑后导出，再让助手用 `import-state` 导入。页面会显示当前保存方式。\n\n常用对话：\n\n- “启动我的工作流工作台，数据放到这个目录。”\n- “新建一部短剧，先和我确认故事与人物资产，再拆分镜。”\n- “按项目的文戏预设生成这三镜，总计不超过三十秒。”\n- “第 S03 镜视线不对，只重做这一镜，其他保留。”\n- “把这次的避坑经验记到这个项目；把我明确的审美偏好存成全局规则。”\n\n工作台不内置模型和算力。ComfyUI、模型权重、AI 助手权限由用户已有环境提供。工作台本身没有后台服务，不需要 Node.js；Python 负责文件操作和 API 请求，FFmpeg 负责视频检查与基础拼接，Remotion 是可选的剪辑工具。\n"}, {"title": "工作流配置", "body": "# 连接和工作流预设\n\n在设置中填写本地或远程 ComfyUI 基础地址，例如 `http://127.0.0.1:8188`。认证需要 Bearer token 时只填环境变量名，把令牌留在助手的运行环境。不要把 Cookie、账号密码或带密钥的 URL 写进配置。\n\n工作流名称只是便于识别的标签。打开自己真正要用的 ComfyUI 工作流，导出 API 格式 JSON，再导入工作台。API 图的每个节点都有 `class_type` 和 `inputs`；含 `nodes` 的画布 JSON 需要先在 ComfyUI 中另行导出，不能直接提交。\n\n文戏和动作是两个预设，可以导入不同 JSON，也可使用同一张图并指定不同的节点参数覆盖。选择实际的提示词、时长和 seed 槽位；参考素材按“节点 ID.输入名 → 资产 ID”绑定。覆盖参数也使用同一槽位格式，例如 `12.strength_model`。不要把特定作者的 LoRA 文件名当成每个用户都已安装的依赖。\n\n运行 `doctor` 检查连接和工具；运行 `preflight --project 项目ID` 检查实际节点、必填参数、连接和枚举值。未映射时长就沿用原图真实时长，预检要求镜头时长和原图一致；不要只在提示词里写十秒而让节点仍生成五秒。\n\n生成需显式 `run --project 项目ID --execute`。任务指纹避免同一镜重复提交；POST 出错或超时会记录 `submission_unknown`，需要查原任务并确认，不自动重发。排队、执行、下载、技术检查、视审和用户验收是不同状态。\n\nAPI 依据：[ComfyUI Server Routes](https://docs.comfy.org/development/comfyui-server/comms_routes)。工作台不从浏览器直接调用云端 API，助手通过本地 Python 客户端调用，避免依赖页面跨域设置。现阶段支持普通 API 节点图，专有代理认证和界面子图需按实际环境适配。\n"}, {"title": "H3 提示词", "body": "# MiniMax H3 提示词\n\n官方入口：[h3-prompt-writing](https://github.com/MiniMax-AI/MiniMax-H3/blob/main/skills/h3-prompt-writing/SKILL.md)。写提示词前运行 `guide refresh`，把官方入口和它引用的 `references/base-en.txt`、`references/ref-en.txt` 缓存到工作目录；每份记录下载时间、来源和 SHA256。刷新失败保留上次成功文件，不以空内容替换。\n\n2026-11-13核对的结构：\n\n| 输入模式 | 描述结构 |\n|---|---|\n| T2VA、I2VA、FL2VA、L2VA | `integrated_multimodal_description`、`overall_soundscape`、`non_diegetic_music` |\n| Ref2VA 全参考 | `subject_definitions`、`summary`、`retention_analysis`、`detailed_description`、`overall_soundscape`、`non_diegetic_music` |\n\n描述用英文，准确台词、歌词和需要出现的画面字保留原语言。不要把中文镜头标题或梗概混进生成描述，防止被误念成台词。按实际上传顺序绑定图片、音频、人物和说话人编号；身份参考、精确首尾帧和音色参考的含义不同。\n\n逐时间段说明构图、人物、场地、动作、相机、声音以及结束状态。首次独立十秒是本工作流的编排起点，不是模型固定限制；补拍按真实需要，节点范围与帧对齐以当前实例为准。官方内容更新后优先读取最新缓存，适用的个人规则仍保留；指南不能替代实际产物的视审。\n"}, {"title": "制作与审片", "body": "# 制作与审片\n\n## 先确定可验证的画面\n\n先确定故事事件和人物想得到什么，再固定场地、角色位置、距离、朝向、道具、光线，最后选择机位。建立镜头与近景共用同一空间。正反打成对检查视线和轴线，不能为了同框突然把远处人物挪到一起。\n\n人物定妆、空景与构图分别承担身份、地点和站位约束。参考图错了先修图。近景正脸清楚，远景优先背面；同框听者写清闭嘴、看谁、如何反应，不跟着说话者对口型。手势有开始、路径和收尾，动作与特效遵循接触、离开、结果的顺序。\n\n## 三轮检查\n\n| 阶段 | 检查内容 |\n|---|---|\n| 生成前 | 剧情与镜头状态、参考图、人物编号、提示词模式、实际工作流与预算 |\n| 生成后 | 首0/1/2/4帧、关键动作全过程、末帧；人物、手部、背景、视线、台词、原生口型 |\n| 剪辑后 | 上镜尾部与下镜开头、动作因果、空间、光线、词头词尾、字幕与混音 |\n\n静止表演也使用连续视频，保留自然呼吸、衣料、光影等微动，不能冻结帧或循环帧冒充视频。技术检查记录实际像素、帧率、时长、音轨和解码结果；通过视审另记源文件哈希、取用区间、观察和证据。缺少真实查看能力时保留待审。\n\n重做只影响失败镜头，遵守预算和次数上限。同类问题两次失败后先分析根因并更换参考、机位或生成方式，不无限堆提示词。自动化执行不等于无人验收；最终表演、气氛和审美仍由人确认。\n\n## 剪辑与规则\n\n多条时间码统一映射到修改前的同一条时间线。可见讲话声画保持同源时钟；删句同步画面与字幕，保留尾音和动作落稳。采用的镜头与淘汰候选分开，工作台和实际剪辑保持一致。\n\n共性避坑经验与明确个人品味存为启用规则；单集人物关系和剧情保留在项目。升级安装包不覆盖个人文件。工作区的 `rules.md` 是供阅读的导出，实际修改通过工作台或 `rule` 命令保存到 `workspace.json`。\n"}]};
